import { existsSync, readdirSync, readFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import { pathToFileURL } from "node:url";
const dir = join(process.env.FACTORY_HOME_OVERRIDE || homedir(), ".factory", "plugins", "installed_plugins");
let best = null;
let names = [];
try { names = readdirSync(dir); } catch {}
for (const name of names) {
  try {
    const record = JSON.parse(readFileSync(join(dir, name), "utf8"));
    const root = record.entry?.installPath;
    if (!String(record.pluginId || "").startsWith("openviking-memory@") || !root) continue;
    const server = join(root, "servers", "mcp-proxy.mjs");
    if (!existsSync(server)) continue;
    const at = Date.parse(record.entry.lastUpdated || record.entry.installedAt || "") || 0;
    if (!best || at > best.at) best = { server, at };
  } catch {}
}
if (!best) { process.stderr.write("openviking-memory: no installed plugin under " + dir + "\n"); process.exit(1); }
process.argv[1] = best.server;
await import(pathToFileURL(best.server).href);
